const page=await figma.getNodeByIdAsync('8:2');
const names=['01_Get_Started','02_Home','03_Wallet','04_Add_Card','05_Payment','06_Receipt'];
const rows=[];
for(const n of names){
  const f=page.children.find(c=>c.name===n);
  if(!f){rows.push({n,missing:true});continue;}
  const linked=f.findAll(x=>x.reactions&&x.reactions.length).map(x=>{
    const r=x.reactions[0]; const a=r.actions&&r.actions[0];
    const dest=a?page.children.concat(awaitAll(page)).find(c=>c.id===a.destinationId):null;
    return x.name+' → '+a.destinationId;
  });
  rows.push({n,frames:f.id,links:linked});
}
async function awaitAll(p){
  const out=[];
  for(const c of p.children) out.push(c);
  return out;
}
const flows=page.flowStartingPoints||[];
return JSON.stringify({rows,flows});

